USE petshop_central;
CREATE TABLE IF NOT EXISTS produtos (id INT AUTO_INCREMENT PRIMARY KEY,codigo VARCHAR(30) NOT NULL UNIQUE,nome VARCHAR(150) NOT NULL,categoria VARCHAR(80),preco DECIMAL(10,2) NOT NULL,estoque INT NOT NULL DEFAULT 0,estoque_minimo INT NOT NULL DEFAULT 5,ativo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS pedidos (id INT AUTO_INCREMENT PRIMARY KEY,numero VARCHAR(30) NOT NULL UNIQUE,cliente_id INT NULL,data_hora DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,total DECIMAL(10,2) NOT NULL,status VARCHAR(30) NOT NULL,forma_pagamento VARCHAR(30),FOREIGN KEY(cliente_id) REFERENCES clientes(id));
CREATE TABLE IF NOT EXISTS pedido_itens (id INT AUTO_INCREMENT PRIMARY KEY,pedido_id INT NOT NULL,produto_id INT NOT NULL,quantidade INT NOT NULL,valor_unitario DECIMAL(10,2) NOT NULL,FOREIGN KEY(pedido_id) REFERENCES pedidos(id) ON DELETE CASCADE,FOREIGN KEY(produto_id) REFERENCES produtos(id));
